#include <cstddef>
#include <initializer_list>
#include <iostream>

int main() {
    for (std::size_t n : {1U, 4U, 8U, 16U}) {
        std::size_t linear = 0;
        for (std::size_t i = 0; i < n; ++i) {
            ++linear;
        }
        std::size_t pairs = 0;
        for (std::size_t i = 0; i < n; ++i) {
            for (std::size_t j = 0; j < i; ++j) {
                ++pairs;
            }
        }
        std::size_t halves = 0;
        for (std::size_t remaining = n; remaining > 0; remaining /= 2) {
            ++halves;
        }
        std::cout << n << ": linear=" << linear
                  << ", pairs=" << pairs
                  << ", halving=" << halves << '\n';
    }
}
